post.warpShader:
uniform sampler2D tDiffuse; uniform vec2 uC; uniform float uA0, uA1, uAsp, uHeat, uHaze, uHR, uTime; varying vec2 vUv;
float nfH(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float nfN(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f); return mix(mix(nfH(i), nfH(i + vec2(1.0, 0.0)), f.x), mix(nfH(i + vec2(0.0, 1.0)), nfH(i + 1.0), f.x), f.y); }
vec2 wave(vec2 uv, float age){ if (age < 0.0 || age > 0.7) return vec2(0.0); vec2 d = uv - uC; d.x *= uAsp;
  float r = length(d), R = 0.04 + age * 0.9, w = 0.035 + age * 0.05; return normalize(d + 1e-5) * exp(-pow((r - R) / w, 2.0)) * (1.0 - age / 0.7); }
void main(){
  vec2 d = vUv - uC; d.x *= uAsp; float m = 1.0 - smoothstep(uHR * 0.4, uHR, length(d));
  vec2 heat = vec2(sin(vUv.y * 90.0 + uTime * 7.0), cos(vUv.x * 80.0 - uTime * 6.0)) * 0.0025 * uHeat * m;
  // haze: irregular blobs rising through the area (realistic fire), two octaves of value noise
  vec2 hq = vec2(vUv.x * uAsp, vUv.y) * 14.0 - vec2(0.0, uTime * 1.6), hq2 = hq * 2.3 - vec2(0.0, uTime * 2.4);
  heat += (vec2(nfN(hq), nfN(hq + vec2(5.2, 1.3))) - 0.5 + 0.5 * (vec2(nfN(hq2 + 9.1), nfN(hq2 + 3.7)) - 0.5)) * 0.014 * uHaze * m;
  vec2 dir = wave(vUv, uA0) + wave(vUv, uA1); dir.x /= uAsp;
  vec2 uv = vUv - dir * 0.035 + heat, ca = dir * 0.008;
  vec4 c = texture2D(tDiffuse, uv);
  gl_FragColor = vec4(texture2D(tDiffuse, uv + ca).r, c.g, texture2D(tDiffuse, uv - ca).b, c.a);
}

post.pixelShader:
uniform sampler2D tDiffuse; uniform float uRows; varying vec2 vUv;
uniform vec3 uPal[24]; uniform int uPalN;
const float BAYER[16] = float[16](0.,8.,2.,10., 12.,4.,14.,6., 3.,11.,1.,9., 15.,7.,13.,5.);
void main(){
  vec2 res = vec2(textureSize(tDiffuse, 0));
  vec2 cell = vec2(max(1.0, floor(res.y / uRows))) / res;
  vec2 id = floor(vUv / cell);
  vec4 c = texture2D(tDiffuse, (id + 0.5) * cell);
  if (uPalN < 2) { gl_FragColor = vec4(floor(c.rgb * 6.0 + 0.5) / 6.0, c.a); return; }
  vec3 a = uPal[0], b = uPal[0];
  float da = 1e9, db = 1e9;
  for (int i = 0; i < 24; i++) {
    if (i >= uPalN) break;
    vec3 e = c.rgb - uPal[i];
    float d = dot(e, e);
    if (d < da) { db = da; b = a; da = d; a = uPal[i]; }
    else if (d < db) { db = d; b = uPal[i]; }
  }
  // how far the colour sits from the nearest (0) towards the second nearest (0.5 = halfway);
  // only the half next to the midpoint dithers, so flat areas stay flat
  vec3 ab = b - a;
  float t = clamp(dot(c.rgb - a, ab) / max(dot(ab, ab), 1e-6), 0.0, 0.5) * 2.0 - 0.5;
  ivec2 m = ivec2(mod(id, 4.0));
  float th = (BAYER[m.y * 4 + m.x] + 0.5) / 16.0;
  gl_FragColor = vec4(t > th ? b : a, c.a);
}

glsl.toon:
#ifdef TOON_ADD
  {
    // additive glow: coverage (clamped brightness x alpha) picks the band,
    // so wide soft halos shrink to their core instead of filling the screen
    float _m = max(max(gl_FragColor.r, gl_FragColor.g), gl_FragColor.b);
    float _i = min(_m, 1.0) * gl_FragColor.a;
    if (_i < 0.4) discard;
    vec3 _h = gl_FragColor.rgb / max(_m, 1e-4);
    vec3 _c = _i < 0.48 ? vec3(0.015, 0.015, 0.02)
            : _i < 0.65 ? _h * 0.72
            : _i < 0.85 ? _h * 0.9
            : mix(_h, vec3(1.0), _m * gl_FragColor.a > 1.6 ? 0.65 : 0.2);
    gl_FragColor = vec4(_c, 1.0);
  }
#else
  if (gl_FragColor.a < 0.5) discard;
  gl_FragColor = vec4(floor(gl_FragColor.rgb * 5.0 + 0.5) / 5.0, 1.0);
#endif

glsl.puppetHead:
uniform vec3 uPinP[8], uPinD[8];
uniform int uPinN;
uniform float uPinR;
// normalised gaussian blend: pins left in place hold the shape around them
vec3 nfPuppet(vec3 w) {
  vec3 sum = vec3(0.0); float ws = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= uPinN) break;
    vec3 d = w - uPinP[i];
    float g = exp(-dot(d, d) / (uPinR * uPinR) * 3.0);
    sum += uPinD[i] * g; ws += g;
  }
  return w + sum / max(1.0, ws);
}

glsl.puppetTail:
if (uPinN > 0) {
  mat4 nfVP = projectionMatrix * viewMatrix;
  vec4 nfW = inverse(nfVP) * gl_Position;
  gl_Position = nfVP * vec4(nfPuppet(nfW.xyz / nfW.w), 1.0);
}

shaders.vertex:
