uniform int uPinN;
uniform float uPinR;
// normalised gaussian blend: pins left in place hold the shape around them
vec3 nfPuppet(vec3 w) {
  vec3 sum = vec3(0.0); float ws = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= uPinN) break;
    vec3 d = w - uPinP[i];
    float g = exp(-dot(d, d) / (uPinR * uPinR) * 3.0);
    sum += uPinD[i] * g; ws += g;
  }
  return w + sum / max(1.0, ws);
}

varying vec3 vN; varying vec3 vV; varying vec3 vP; varying float vWY;
void main(){
  vN = normalize(normalMatrix * normal); vP = position;
  vec4 w = modelMatrix * vec4(position, 1.0); vWY = w.y;
  vec4 mv = viewMatrix * w; vV = normalize(-mv.xyz);
  gl_Position = projectionMatrix * mv;

  if (uPinN > 0) {
    mat4 nfVP = projectionMatrix * viewMatrix;
    vec4 nfW = inverse(nfVP) * gl_Position;
    gl_Position = nfVP * vec4(nfPuppet(nfW.xyz / nfW.w), 1.0);
  }
}

shaders.fragment:
uniform vec3 uPal[5]; uniform vec3 uInk;
uniform float uGlow, uFlash, uAlpha, uDissolve, uFloorY, uInkOnly;
varying vec3 vN; varying vec3 vV; varying vec3 vP; varying float vWY;
float h3(vec3 p){ return fract(sin(dot(floor(p), vec3(12.9898, 78.233, 37.719))) * 43758.5453); }
void main(){
  if (vWY < uFloorY) discard;
  // dissolve from the tip up in blocky chunks
  if (uDissolve > 0.0 && vP.y + 0.25 * h3(vP * 28.0) < uDissolve * 1.3) discard;
  if (uInkOnly > 0.5) { gl_FragColor = vec4(uInk, uAlpha); return; }
  vec3 n = normalize(vN);
  float d = dot(n, normalize(vec3(-0.45, 0.6, 0.65))) + 0.25 * (1.0 - vP.y);
  vec3 c = d < 0.05 ? uPal[1] : d < 0.45 ? uPal[2] : d < 0.8 ? uPal[3] : uPal[4];
  float rim = 1.0 - abs(dot(n, normalize(vV)));
  float hot = 0.0;
  if (rim > 0.75) { c = uPal[4]; hot = 1.0; }
  // bright fuller line down the blade
  if (abs(vP.x) < 0.012 && vP.y < 0.6) { c = uPal[4]; hot = 1.0; }
  c *= mix(1.0, uGlow, 0.7 * hot);
  c = mix(c, uPal[4] * 1.3, uFlash);
  gl_FragColor = vec4(c, uAlpha);
}
